const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Point near Hotan in the Taklamakan Desert, buffered for a small analysis area.
  const hotanPoint = ee.Geometry.Point([79.9, 37.5]);
  const geometry = hotanPoint.buffer(5000); // 5km buffer

  // Date ranges: 1-month window around the specified dates to ensure enough images.
  const startDate1 = '2020-02-23';
  const endDate1 = '2020-03-23'; // 1 month after startDate1
  const startDate2 = '2020-04-29';
  const endDate2 = '2020-05-29'; // 1 month after startDate2

  // Function to mask clouds from Sentinel-2 SR data.
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    // Bits 10 and 11 are clouds and cirrus, respectively.
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    // Both flags should be set to zero, indicating clear conditions.
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
      .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask).divide(10000); // Scale to SR range [0, 1]
  }

  // Function to calculate NDVI.
  function addNDVI(image) {
    return image.addBands(image.normalizedDifference(['B8', 'B4']).rename('NDVI'));
  }

  // 2. Data Acquisition & Check
  const s2_collection = ee.ImageCollection('COPERNICUS/S2_SR')
    .filterBounds(geometry);

  // Period 1
  let collection1 = s2_collection
    .filterDate(startDate1, endDate1)
    .map(maskS2clouds)
    .map(addNDVI);

  const size1 = await collection1.size().getInfo();
  if (size1 === 0) {
    console.log(`No images found for Period 1 (${startDate1} to ${endDate1}).`);
    console.log("C1");
    return;
  }

  // Period 2
  let collection2 = s2_collection
    .filterDate(startDate2, endDate2)
    .map(maskS2clouds)
    .map(addNDVI);

  const size2 = await collection2.size().getInfo();
  if (size2 === 0) {
    console.log(`No images found for Period 2 (${startDate2} to ${endDate2}).`);
    console.log("C1");
    return;
  }

  // Calculate mean NDVI for each period.
  const meanNDVI1 = collection1.select('NDVI').mean();
  const meanNDVI2 = collection2.select('NDVI').mean();

  // 3. Processing & Calculation
  const scale = 1000; // Use a larger scale for faster processing and to avoid timeouts.
  const maxPixels = 1e9;

  // Reduce region for Period 1
  const stats1 = await meanNDVI1.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: geometry,
    scale: scale,
    maxPixels: maxPixels
  }).getInfo();

  const ndvi1 = stats1 && stats1.NDVI;
  const pixels1 = stats1 && stats1.NDVI_count;

  if (ndvi1 === null || pixels1 === null || pixels1 === 0) {
    console.log(`Period 1 (${startDate1} to ${endDate1}) calculation failure or no valid pixels.`);
    console.log(`Images: ${size1}, Valid Pixels: ${pixels1}`);
    if (pixels1 === 0) {
      console.log("C2");
    } else {
      console.log("C3");
    }
    return;
  }

  // Reduce region for Period 2
  const stats2 = await meanNDVI2.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: geometry,
    scale: scale,
    maxPixels: maxPixels
  }).getInfo();

  const ndvi2 = stats2 && stats2.NDVI;
  const pixels2 = stats2 && stats2.NDVI_count;

  if (ndvi2 === null || pixels2 === null || pixels2 === 0) {
    console.log(`Period 2 (${startDate2} to ${endDate2}) calculation failure or no valid pixels.`);
    console.log(`Images: ${size2}, Valid Pixels: ${pixels2}`);
    if (pixels2 === 0) {
      console.log("C2");
    } else {
      console.log("C3");
    }
    return;
  }

  // 4. Validation & Final Answer
  console.log(`Period 1 (${startDate1} to ${endDate1}): Images: ${size1}, Mean NDVI: ${ndvi1.toFixed(3)}, Pixels: ${pixels1}`);
  console.log(`Period 2 (${startDate2} to ${endDate2}): Images: ${size2}, Mean NDVI: ${ndvi2.toFixed(3)}, Pixels: ${pixels2}`);

  if (ndvi2 > ndvi1) {
    console.log("A"); // Vegetation cover increased
  } else {
    console.log("B"); // Vegetation cover did not increase
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
